import type { LocaleCode, ProfileVisibility } from '@infra/db/database.types';
import { demoPhone } from '@infra/phone/demo-phone';

import type { Rgb } from './documents';

/**
 * The cast: who a tester can sign in as, and what each of them is in the middle of.
 *
 * **Declared with dictionary codes, never ids.** Every id in this product is a UUID
 * generated by `pnpm seed`, so it differs per database and a fixture holding one
 * would be unusable on the next machine. The seeder resolves each code once and fails
 * by name if a dictionary revision removes one — which is the failure you want, since
 * the alternative is a profile that silently binds nothing and renders "Unavailable
 * value" (CLAUDE.md's id/code rule, one layer down).
 *
 * **The cast is chosen to cover states, not to be a plausible sample.** Six candidates
 * is one per §2.1 category plus one deliberately unfinished; three employers cover
 * verified, awaiting verification, and individual rather than company. A seventh
 * plausible candidate would test nothing a tester cannot already reach.
 *
 * **The numbers are all `+99801…`** — see `demo-phone.ts`. They are grouped by role so
 * that a tester reading the document can tell what they are logging into before they
 * log in: `1` is a candidate, `2` an employer, `9` an administrator.
 *
 * **The codes are memorable on purpose.** They are published in
 * `docs/TEST_ACCOUNTS.md`; a shared credential nobody can remember gets written on a
 * sticky note, and there is nothing here to protect — the numbers cannot exist and
 * the accounts hold invented data.
 */

/** A ground colour per person, so the avatar in a screenshot identifies the account. */
const NAVY: Rgb = [0x14, 0x2c, 0x4a];
const TURQUOISE: Rgb = [0x1f, 0x6f, 0x8b];
const CLAY: Rgb = [0x8b, 0x4a, 0x2f];
const MOSS: Rgb = [0x3d, 0x6b, 0x35];
const PLUM: Rgb = [0x5b, 0x3a, 0x63];
const SLATE: Rgb = [0x44, 0x4f, 0x5a];

/**
 * A category field's value.
 *
 * A dictionary-backed one names **which** dictionary, rather than leaving the seeder
 * to infer it from the field's name. The first attempt inferred it from an `_ids`
 * suffix and got `specialization` wrong — it is a `dictionary_multi` over the
 * `specialization` type, not free text and not an `attribute` — which the field
 * validator caught, and would not have caught if the guess had merely picked the wrong
 * dictionary of ids.
 */
export type DemoAttribute =
  | string
  | number
  | boolean
  | { dictionary: string; codes: string[] };

export interface DemoExperience {
  employerName: string;
  roleTitle: string;
  occupationCode?: string;
  startedOn: string;
  endedOn?: string;
  isCurrent?: boolean;
  responsibilities: string;
}

export interface DemoEducation {
  levelCode: string;
  institution: string;
  specialization: string;
  graduationYear: number;
}

export interface DemoCandidate {
  key: string;
  phone: string;
  code: string;
  fullName: string;
  initials: string;
  ground: Rgb;
  locale: LocaleCode;
  headline: string;
  /** What a tester should look at on this account. Reproduced in the document. */
  purpose: string;

  dateOfBirth: string;
  genderCode: string;
  regionCode: string;
  districtCode: string;
  settlement: string;
  occupationCode: string;
  occupationLevelCode: string;
  additionalOccupationCodes: string[];
  skills: { code: string; levelCode: string }[];
  languages: { code: string; levelCode: string }[];
  employmentTypeCodes: string[];
  workFormatCodes: string[];
  salaryFrom: number;
  salaryTo: number;
  salaryPeriodCode: string;
  availableFrom: string;
  willingToRelocate: boolean;
  willingToTravel: boolean;
  /** Category fields, by code. Only the ones the candidate's category declares. */
  attributes: Record<string, DemoAttribute>;
  experience: DemoExperience[];
  education: DemoEducation[];
  visibility: ProfileVisibility;
  /** A generated CV, uploaded through the real file store. */
  wantsCv: boolean;
  wantsPhoto: boolean;
  summary: string;
}

export interface DemoVacancy {
  key: string;
  title: string;
  occupationCode: string;
  description: string;
  workerCount: number;
  regionCode: string;
  districtCode: string;
  address: string;
  employmentTypeCodes: string[];
  workFormatCodes: string[];
  shiftCodes?: string[];
  hoursPerDay?: number;
  salaryFrom: number;
  salaryTo: number;
  salaryPeriodCode: string;
  startsOn?: string;
  endsOn?: string;
  deadlineOn?: string;
  skills?: { code: string; levelCode: string; mandatory: boolean }[];
  languages?: { code: string; levelCode: string; mandatory: boolean }[];
  /** Where the vacancy should end up. `draft` is never submitted. */
  land: 'active' | 'paused' | 'under_moderation' | 'draft';
}

export interface DemoEmployer {
  key: string;
  phone: string;
  code: string;
  type: 'company' | 'individual';
  contactName: string;
  initials: string;
  ground: Rgb;
  locale: LocaleCode;
  purpose: string;

  legalName?: string;
  publicName?: string;
  industryCode?: string;
  regionCode: string;
  districtCode: string;
  address: string;
  description: string;
  contactPhone: string;
  /** `verified` runs the real admin decision; `under_review` leaves it in the queue. */
  verification: 'verified' | 'under_review';
  wantsLogo: boolean;
  vacancies: DemoVacancy[];
}

export interface DemoAdmin {
  key: string;
  phone: string;
  code: string;
  fullName: string;
  locale: LocaleCode;
  purpose: string;
}

