/** Every seeded account, in the order the document lists them. */
export function demoRoster(): {
  phone: string;
  code: string;
  label: string;
  role: string;
  purpose: string;
}[] {
  return [
    ...DEMO_CANDIDATES.map((c) => ({
      phone: c.phone,
      code: c.code,
      label: `${c.fullName} — ${c.headline}`,
      role: 'candidate',
      purpose: c.purpose,
    })),
    ...DEMO_EMPLOYERS.map((e) => ({
      phone: e.phone,
      code: e.code,
      label: `${e.publicName ?? e.contactName} — ${e.contactName}`,
      role: 'employer',
      purpose: e.purpose,
    })),
    {
      phone: DEMO_ADMIN.phone,
      code: DEMO_ADMIN.code,
      label: DEMO_ADMIN.fullName,
      role: 'admin',
      purpose: DEMO_ADMIN.purpose,
    },
  ];
}
